create table if not exists public.videographer_access ( profile_id uuid primary key references public.profiles (id) on delete cascade, share_with_client boolean not null default false, updated_by uuid references public.profiles (id) on delete set null, updated_at timestamptz not null default now() ); alter table public.videographer_access enable row level security; drop policy if exists "videographer_access: ceo" on public.videographer_access; create policy "videographer_access: ceo" on public.videographer_access for all using (public.is_ceo_role()) with check (public.is_ceo_role()); drop policy if exists "videographer_access: read own" on public.videographer_access; create policy "videographer_access: read own" on public.videographer_access for select using (profile_id = auth.uid()); create or replace function public.videographer_can_share() returns boolean language sql stable security definer set search_path = public as $$ select public.current_role() = 'videographer' and coalesce( (select share_with_client from public.videographer_access where profile_id = auth.uid()), false ); $$; revoke all on function public.videographer_can_share() from public; grant execute on function public.videographer_can_share() to authenticated; drop policy if exists "submissions: videographer create own" on public.submissions; create policy "submissions: videographer create own" on public.submissions for insert with check ( public.current_role() = 'videographer' and created_by = auth.uid() and (visibility = 'team_only' or public.videographer_can_share()) );
